package vercel_test

import (
	"context"
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/acctest"
	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/terraform"
	"github.com/vercel/terraform-provider-vercel/v5/client"
)

func testCheckVCRRepositoryPermissionExists(testClient *client.Client, teamID string, n string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("not found: %s", n)
		}

		if rs.Primary.ID == "" {
			return fmt.Errorf("no ID is set")
		}

		projectID := rs.Primary.Attributes["project_id"]
		repository := rs.Primary.Attributes["repository"]
		grantedTeamID := rs.Primary.Attributes["granted_team_id"]

		_, err := testClient.GetVCRRepositoryPermission(context.TODO(), client.GetVCRRepositoryPermissionRequest{
			TeamID:        teamID,
			ProjectID:     projectID,
			IDOrName:      repository,
			GrantedTeamID: grantedTeamID,
		})
		if client.NotFound(err) {
			return fmt.Errorf("test failed because the vcr repository permission %s %s %s %s - %s could not be found", teamID, projectID, repository, grantedTeamID, rs.Primary.ID)
		}
		return err
	}
}

func TestAcc_VCRRepositoryPermissionResource(t *testing.T) {
	projectSuffix := acctest.RandString(16)
	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
		CheckDestroy:             testAccProjectDestroy(testClient(t), "vercel_project.test", testTeam(t)),
		Steps: []resource.TestStep{
			{
				Config: cfg(testAccVCRRepositoryPermission(projectSuffix, testTeam(t))),
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckVCRRepositoryPermissionExists(testClient(t), testTeam(t), "vercel_vcr_repository_permission.test"),
					resource.TestCheckResourceAttrSet("vercel_vcr_repository_permission.test", "id"),
					resource.TestCheckResourceAttrSet("vercel_vcr_repository_permission.test", "repository_id"),
					resource.TestCheckResourceAttr("vercel_vcr_repository_permission.test", "granted_team_id", testTeam(t)),
					resource.TestCheckResourceAttrSet("vercel_vcr_repository_permission.test", "granted_team_slug"),
				),
			},
			{
				ResourceName:      "vercel_vcr_repository_permission.test",
				ImportState:       true,
				ImportStateVerify: true,
				ImportStateIdFunc: getVCRRepositoryPermissionImportID("vercel_vcr_repository_permission.test"),
			},
		},
	})
}

func getVCRRepositoryPermissionImportID(n string) resource.ImportStateIdFunc {
	return func(s *terraform.State) (string, error) {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return "", fmt.Errorf("not found: %s", n)
		}

		if rs.Primary.ID == "" {
			return "", fmt.Errorf("no ID is set")
		}

		return fmt.Sprintf("%s/%s/%s/%s",
			rs.Primary.Attributes["team_id"],
			rs.Primary.Attributes["project_id"],
			rs.Primary.Attributes["repository"],
			rs.Primary.Attributes["granted_team_id"],
		), nil
	}
}

func testAccVCRRepositoryPermission(projectSuffix, grantedTeamID string) string {
	return fmt.Sprintf(`
resource "vercel_project" "test" {
  name = "test-acc-vcr-perm-%[1]s"
}

resource "vercel_vcr_repository" "test" {
  project_id = vercel_project.test.id
  name       = "test-acc-%[1]s"
}

resource "vercel_vcr_repository_permission" "test" {
  project_id      = vercel_project.test.id
  repository      = vercel_vcr_repository.test.name
  granted_team_id = "%[2]s"
}
`, projectSuffix, grantedTeamID)
}

package vercel_test

import (
	"context"
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/acctest"
	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/terraform"
	"github.com/vercel/terraform-provider-vercel/v5/client"
)

func testCheckOAuthAppExists(testClient *client.Client, teamID, n string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("not found: %s", n)
		}
		if rs.Primary.ID == "" {
			return fmt.Errorf("no ID is set")
		}

		_, err := testClient.GetOAuthApp(context.TODO(), rs.Primary.ID, teamID)
		return err
	}
}

func testCheckOAuthAppDoesNotExist(testClient *client.Client, teamID, n string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("not found: %s", n)
		}

		_, err := testClient.GetOAuthApp(context.TODO(), rs.Primary.ID, teamID)
		if err == nil {
			return fmt.Errorf("expected not_found error, but got no error")
		}
		if !client.OAuthAppNotFound(err) {
			return fmt.Errorf("Unexpected error checking for deleted oauth app: %s", err)
		}

		return nil
	}
}

func getOAuthAppImportID(n string) resource.ImportStateIdFunc {
	return func(s *terraform.State) (string, error) {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return "", fmt.Errorf("not found: %s", n)
		}
		if rs.Primary.ID == "" {
			return "", fmt.Errorf("no ID is set")
		}
		return fmt.Sprintf("%s/%s", rs.Primary.Attributes["team_id"], rs.Primary.ID), nil
	}
}

func TestAcc_OAuthAppResource(t *testing.T) {
	name := acctest.RandString(16)
	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
		CheckDestroy: resource.ComposeAggregateTestCheckFunc(
			testCheckOAuthAppDoesNotExist(testClient(t), testTeam(t), "vercel_oauth_app.test"),
		),
		Steps: []resource.TestStep{
			{
				// Minimal config: neither redirect_uris nor scopes set, covering
				// the null-set handling in Create.
				Config: cfg(testAccResourceOAuthApp(name)),
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckOAuthAppExists(testClient(t), testTeam(t), "vercel_oauth_app.test"),
					resource.TestCheckResourceAttrSet("vercel_oauth_app.test", "id"),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "name", fmt.Sprintf("test acc %s", name)),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "slug", fmt.Sprintf("test-acc-%s", name)),
					resource.TestCheckNoResourceAttr("vercel_oauth_app.test", "redirect_uris"),
					// The API force-includes openid even when scopes are unset.
					resource.TestCheckTypeSetElemAttr("vercel_oauth_app.test", "scopes.*", "openid"),
				),
			},
			{
				ResourceName:      "vercel_oauth_app.test",
				ImportState:       true,
				ImportStateIdFunc: getOAuthAppImportID("vercel_oauth_app.test"),
			},
			{
				Config: cfg(testAccResourceOAuthAppUpdated(name)),
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckOAuthAppExists(testClient(t), testTeam(t), "vercel_oauth_app.test"),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "name", fmt.Sprintf("test acc %s updated", name)),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "description", "An updated description."),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "home_page_uri", "https://example.com"),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "redirect_uris.#", "2"),
					resource.TestCheckTypeSetElemAttr("vercel_oauth_app.test", "redirect_uris.*", "https://example.com/other/callback"),
					resource.TestCheckResourceAttr("vercel_oauth_app.test", "scopes.#", "4"),
					resource.TestCheckTypeSetElemAttr("vercel_oauth_app.test", "scopes.*", "offline_access"),
				),
			},
		},
	})
}

func TestAcc_OAuthAppClientSecretResource(t *testing.T) {
	name := acctest.RandString(16)
	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
		CheckDestroy: resource.ComposeAggregateTestCheckFunc(
			testCheckOAuthAppDoesNotExist(testClient(t), testTeam(t), "vercel_oauth_app.test"),
		),
		Steps: []resource.TestStep{
			{
				Config: cfg(testAccResourceOAuthAppClientSecret(name)),
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckOAuthAppExists(testClient(t), testTeam(t), "vercel_oauth_app.test"),
					resource.TestCheckResourceAttrSet("vercel_oauth_app_client_secret.test", "id"),
					resource.TestCheckResourceAttrSet("vercel_oauth_app_client_secret.test", "client_secret"),
					resource.TestCheckResourceAttrSet("vercel_oauth_app_client_secret.test", "last_four_chars"),
					testCheckOAuthAppClientSecretExists(testClient(t), testTeam(t), "vercel_oauth_app_client_secret.test"),
				),
			},
		},
	})
}

func testCheckOAuthAppClientSecretExists(testClient *client.Client, teamID, n string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("not found: %s", n)
		}

		app, err := testClient.GetOAuthApp(context.TODO(), rs.Primary.Attributes["oauth_app_id"], teamID)
		if err != nil {
			return err
		}
		lastFour := rs.Primary.Attributes["last_four_chars"]
		for _, secret := range app.ClientSecrets {
			if secret.LastFourChars == lastFour {
				return nil
			}
		}
		return fmt.Errorf("no client secret with last four chars %q found on app", lastFour)
	}
}

func testAccResourceOAuthApp(name string) string {
	return fmt.Sprintf(`
resource "vercel_oauth_app" "test" {
	name = "test acc %[1]s"
	slug = "test-acc-%[1]s"
}
`, name)
}

func testAccResourceOAuthAppUpdated(name string) string {
	return fmt.Sprintf(`
resource "vercel_oauth_app" "test" {
	name        = "test acc %[1]s updated"
	slug        = "test-acc-%[1]s"
	description = "An updated description."

	home_page_uri = "https://example.com"

	redirect_uris = [
		"https://example.com/api/auth/callback",
		"https://example.com/other/callback",
	]

	scopes = ["openid", "email", "profile", "offline_access"]
}
`, name)
}

func testAccResourceOAuthAppClientSecret(name string) string {
	return fmt.Sprintf(`
resource "vercel_oauth_app" "test" {
	name = "test acc %[1]s"
	slug = "test-acc-%[1]s"

	redirect_uris = ["https://example.com/api/auth/callback"]
}

resource "vercel_oauth_app_client_secret" "test" {
	oauth_app_id = vercel_oauth_app.test.id
}
`, name)
}

package vercel_test

import (
	"context"
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/acctest"
	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/plancheck"
	"github.com/hashicorp/terraform-plugin-testing/terraform"

	"github.com/vercel/terraform-provider-vercel/v5/client"
)

func testCheckAIGatewayAPIKeyExists(testClient *client.Client, n string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("not found: %s", n)
		}
		if rs.Primary.ID == "" {
			return fmt.Errorf("no ID is set")
		}

		_, err := testClient.GetAIGatewayAPIKey(context.TODO(), rs.Primary.ID, rs.Primary.Attributes["team_id"])
		if err != nil {
			return fmt.Errorf("error getting AI Gateway API key %s: %w", rs.Primary.ID, err)
		}
		return nil
	}
}

func testCheckAIGatewayAPIKeyDeleted(testClient *client.Client, n string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[n]
		if !ok {
			return fmt.Errorf("not found: %s", n)
		}

		_, err := testClient.GetAIGatewayAPIKey(context.TODO(), rs.Primary.ID, rs.Primary.Attributes["team_id"])
		if err == nil {
			return fmt.Errorf("expected AI Gateway API key to be deleted")
		}
		if !client.NotFound(err) {
			return fmt.Errorf("unexpected error checking for deleted AI Gateway API key: %w", err)
		}
		return nil
	}
}

func TestAcc_AIGatewayAPIKeyResource(t *testing.T) {
	name := "test-api-key-" + acctest.RandString(16)

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
		CheckDestroy:             testCheckAIGatewayAPIKeyDeleted(testClient(t), "vercel_ai_gateway_api_key.test"),
		Steps: []resource.TestStep{
			{
				Config: cfg(testAccAIGatewayAPIKey(name)),
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckAIGatewayAPIKeyExists(testClient(t), "vercel_ai_gateway_api_key.test"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "name", name),
					resource.TestCheckResourceAttrSet("vercel_ai_gateway_api_key.test", "id"),
					resource.TestCheckResourceAttrSet("vercel_ai_gateway_api_key.test", "team_id"),
					resource.TestCheckResourceAttrSet("vercel_ai_gateway_api_key.test", "api_key_string"),
					resource.TestCheckResourceAttrSet("vercel_ai_gateway_api_key.test", "partial_key"),
				),
			},
			{
				// Renaming is an in-place update; the key is not replaced and
				// the secret is preserved.
				Config: cfg(testAccAIGatewayAPIKey(name + "-renamed")),
				ConfigPlanChecks: resource.ConfigPlanChecks{
					PreApply: []plancheck.PlanCheck{
						plancheck.ExpectResourceAction("vercel_ai_gateway_api_key.test", plancheck.ResourceActionUpdate),
					},
				},
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckAIGatewayAPIKeyExists(testClient(t), "vercel_ai_gateway_api_key.test"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "name", name+"-renamed"),
					resource.TestCheckResourceAttrSet("vercel_ai_gateway_api_key.test", "api_key_string"),
				),
			},
			{
				ResourceName:            "vercel_ai_gateway_api_key.test",
				ImportState:             true,
				ImportStateVerify:       true,
				ImportStateVerifyIgnore: []string{"api_key_string"},
			},
		},
	})
}

func TestAcc_AIGatewayAPIKeyResourceWithQuota(t *testing.T) {
	name := "test-api-key-quota-" + acctest.RandString(16)

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
		CheckDestroy:             testCheckAIGatewayAPIKeyDeleted(testClient(t), "vercel_ai_gateway_api_key.test"),
		Steps: []resource.TestStep{
			{
				Config: cfg(testAccAIGatewayAPIKeyWithQuota(name, 500, "monthly", "[50, 100]")),
				Check: resource.ComposeAggregateTestCheckFunc(
					testCheckAIGatewayAPIKeyExists(testClient(t), "vercel_ai_gateway_api_key.test"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota.limit_amount", "500"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota.refresh_period", "monthly"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota.alert_thresholds.#", "2"),
				),
			},
			{
				// Quota changes are in-place updates.
				Config: cfg(testAccAIGatewayAPIKeyWithQuota(name, 750, "weekly", "[75]")),
				ConfigPlanChecks: resource.ConfigPlanChecks{
					PreApply: []plancheck.PlanCheck{
						plancheck.ExpectResourceAction("vercel_ai_gateway_api_key.test", plancheck.ResourceActionUpdate),
					},
				},
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota.limit_amount", "750"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota.refresh_period", "weekly"),
					resource.TestCheckResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota.alert_thresholds.#", "1"),
				),
			},
			{
				// Removing the quota archives it in-place.
				Config: cfg(testAccAIGatewayAPIKey(name)),
				ConfigPlanChecks: resource.ConfigPlanChecks{
					PreApply: []plancheck.PlanCheck{
						plancheck.ExpectResourceAction("vercel_ai_gateway_api_key.test", plancheck.ResourceActionUpdate),
					},
				},
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckNoResourceAttr("vercel_ai_gateway_api_key.test", "ai_gateway_quota"),
				),
			},
		},
	})
}

func testAccAIGatewayAPIKey(name string) string {
	return fmt.Sprintf(`
resource "vercel_ai_gateway_api_key" "test" {
  name = "%s"
}
`, name)
}

func testAccAIGatewayAPIKeyWithQuota(name string, limitAmount int, refreshPeriod, alertThresholds string) string {
	return fmt.Sprintf(`
resource "vercel_ai_gateway_api_key" "test" {
  name = "%s"

  ai_gateway_quota = {
    limit_amount     = %d
    refresh_period   = "%s"
    alert_thresholds = %s
  }
}
`, name, limitAmount, refreshPeriod, alertThresholds)
}

package vercel

import (
	"context"
	"fmt"

	"github.com/hashicorp/terraform-plugin-framework-validators/stringvalidator"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/schema/validator"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-log/tflog"
	"github.com/vercel/terraform-provider-vercel/v5/client"
)

var (
	_ resource.Resource                = &vcrRepositoryPermissionResource{}
	_ resource.ResourceWithConfigure   = &vcrRepositoryPermissionResource{}
	_ resource.ResourceWithImportState = &vcrRepositoryPermissionResource{}
)

func newVCRRepositoryPermissionResource() resource.Resource {
	return &vcrRepositoryPermissionResource{}
}

type vcrRepositoryPermissionResource struct {
	client *client.Client
}

func (r *vcrRepositoryPermissionResource) Metadata(_ context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_vcr_repository_permission"
}

func (r *vcrRepositoryPermissionResource) Configure(_ context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}

	client, ok := req.ProviderData.(*client.Client)
	if !ok {
		resp.Diagnostics.AddError(
			"Unexpected Resource Configure Type",
			fmt.Sprintf("Expected *client.Client, got: %T. Please report this issue to the provider developers.", req.ProviderData),
		)
		return
	}

	r.client = client
}

func (r *vcrRepositoryPermissionResource) Schema(_ context.Context, _ resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{
		Description: `
Provides a Vercel Container Registry (VCR) Repository Permission resource.

A VCR Repository Permission shares a VCR Repository with another Vercel Team, granting
it read (pull) access to the repository's images. One resource manages a single grant,
identified by the repository and the team the permission is granted to.
`,
		Attributes: map[string]schema.Attribute{
			"id": schema.StringAttribute{
				Computed:      true,
				Description:   "The ID of this resource. Format: `repository_id/granted_team_id`.",
				PlanModifiers: []planmodifier.String{stringplanmodifier.UseNonNullStateForUnknown()},
			},
			"team_id": schema.StringAttribute{
				Optional:      true,
				Computed:      true,
				PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplaceIfConfigured(), stringplanmodifier.UseNonNullStateForUnknown()},
				Description:   "The ID of the team that owns the repository. Required when configuring a team resource if a default team has not been set in the provider.",
			},
			"project_id": schema.StringAttribute{
				Description:   "The ID of the Vercel Project the repository belongs to.",
				Required:      true,
				PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()},
			},
			"repository": schema.StringAttribute{
				Description:   "The ID or name of the VCR Repository to share.",
				Required:      true,
				PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()},
			},
			"repository_id": schema.StringAttribute{
				Computed:      true,
				Description:   "The ID of the VCR Repository the permission is granted on.",
				PlanModifiers: []planmodifier.String{stringplanmodifier.UseNonNullStateForUnknown()},
			},
			"granted_team_id": schema.StringAttribute{
				Optional:      true,
				Computed:      true,
				Description:   "The ID of the team to grant pull access to. Must specify one of granted_team_id or granted_team_slug.",
				PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplaceIfConfigured(), stringplanmodifier.UseNonNullStateForUnknown()},
				Validators: []validator.String{
					stringvalidator.ExactlyOneOf(
						path.MatchRoot("granted_team_id"),
						path.MatchRoot("granted_team_slug"),
					),
				},
			},
			"granted_team_slug": schema.StringAttribute{
				Optional:      true,
				Computed:      true,
				Description:   "The slug of the team to grant pull access to. Must specify one of granted_team_id or granted_team_slug.",
				PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplaceIfConfigured(), stringplanmodifier.UseNonNullStateForUnknown()},
				Validators: []validator.String{
					stringvalidator.ExactlyOneOf(
						path.MatchRoot("granted_team_id"),
						path.MatchRoot("granted_team_slug"),
					),
				},
			},
		},
	}
}

type VCRRepositoryPermission struct {
	ID              types.String `tfsdk:"id"`
	TeamID          types.String `tfsdk:"team_id"`
	ProjectID       types.String `tfsdk:"project_id"`
	Repository      types.String `tfsdk:"repository"`
	RepositoryID    types.String `tfsdk:"repository_id"`
	GrantedTeamID   types.String `tfsdk:"granted_team_id"`
	GrantedTeamSlug types.String `tfsdk:"granted_team_slug"`
}

func convertResponseToVCRRepositoryPermission(res client.VCRRepositoryPermission, projectID, repository string) VCRRepositoryPermission {
	repositoryID := res.RepositoryID
	if repositoryID == "" {
		repositoryID = repository
	}
	return VCRRepositoryPermission{
		ID:              types.StringValue(repositoryID + "/" + res.GrantedTeamID),
		TeamID:          types.StringValue(res.TeamID),
		ProjectID:       types.StringValue(projectID),
		Repository:      types.StringValue(repository),
		RepositoryID:    types.StringValue(repositoryID),
		GrantedTeamID:   types.StringValue(res.GrantedTeamID),
		GrantedTeamSlug: types.StringValue(res.GrantedTeamSlug),
	}
}

func (p VCRRepositoryPermission) repositoryIDOrName() string {
	if p.RepositoryID.ValueString() != "" {
		return p.RepositoryID.ValueString()
	}
	return p.Repository.ValueString()
}

func (r *vcrRepositoryPermissionResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var plan VCRRepositoryPermission
	diags := req.Plan.Get(ctx, &plan)
