					"refresh_period": schema.StringAttribute{
						Description: "How often the quota refreshes. Must be one of `daily`, `weekly`, `monthly` or `none`. Defaults to `none`.",
						Optional:    true,
						Computed:    true,
						Default:     stringdefault.StaticString("none"),
